package com.dragonbrain.worldgen;

import net.minecraft.registry.RegistryKey;
import net.minecraft.registry.RegistryKeys;
import net.minecraft.registry.tag.TagKey;
import net.minecraft.world.biome.Biome;
import net.minecraft.world.gen.structure.Structure;

import com.dragonbrain.DragonBrain;
import com.dragonbrain.config.ConfigManager;

import net.fabricmc.fabric.api.biome.v1.TheEndBiomes;

import java.util.List;

/**
 * World-generation registrations. Biome and structure *content* lives in
 * datapack JSON under {@code data/dragonbrain/worldgen/} (generated by
 * tools/generate_worldgen.py); this class owns the registry keys and the
 * integration of the custom biomes into the End's biome source via
 * Fabric's {@link TheEndBiomes} API.
 *
 * <p>v3.0 -> v3.1 migration note: custom biomes/structures/features only
 * appear in <b>newly generated chunks</b>. Already-generated End chunks
 * keep their original biomes and content, exactly like vanilla updates.
 */
public final class ModWorldgen {
    public static final RegistryKey<Biome> VOID_GARDENS = biome("void_gardens");
    public static final RegistryKey<Biome> CHORUS_WILDS = biome("chorus_wilds");
    public static final RegistryKey<Biome> SHATTERED_EXPANSE = biome("shattered_expanse");
    public static final RegistryKey<Biome> PETRIFIED_ABYSS = biome("petrified_abyss");
    public static final RegistryKey<Biome> ASTRAL_BARRENS = biome("astral_barrens");

    public static final List<RegistryKey<Biome>> BIOMES = List.of(
            VOID_GARDENS, CHORUS_WILDS, SHATTERED_EXPANSE, PETRIFIED_ABYSS, ASTRAL_BARRENS);
    public static final List<String> BIOME_IDS = BIOMES.stream()
            .map(k -> k.getValue().getPath()).toList();

    public static final List<String> STRUCTURE_IDS = List.of(
            "ancient_end_ruins", "abandoned_observatory", "resonance_vault", "sentinel_sanctuary");

    public static final TagKey<Structure> RIFT_COMPASS_TARGETS =
            TagKey.of(RegistryKeys.STRUCTURE, DragonBrain.id("rift_compass_targets"));

    private ModWorldgen() {
    }

    private static RegistryKey<Biome> biome(String path) {
        return RegistryKey.of(RegistryKeys.BIOME, DragonBrain.id(path));
    }

    public static TagKey<Structure> locateTag(String structureId) {
        return TagKey.of(RegistryKeys.STRUCTURE, DragonBrain.id("locate/" + structureId));
    }

    public static void init() {
        ModFeatures.init();
        if (!ConfigManager.get().customBiomes) {
            DragonBrain.LOGGER.info("Custom End biomes disabled by config (customBiomes=false); "
                    + "biome JSONs remain registered but are not added to the End biome source.");
            return;
        }
        // Outer-island biome placement via Fabric's End biome API. The central
        // arena (main island) is intentionally untouched.
        // Highlands = large outer islands.
        TheEndBiomes.addHighlandsBiome(CHORUS_WILDS, 4.0);
        TheEndBiomes.addHighlandsBiome(VOID_GARDENS, 3.0);
        TheEndBiomes.addHighlandsBiome(PETRIFIED_ABYSS, 2.0);
        // Midlands wrap a specific highlands biome.
        TheEndBiomes.addMidlandsBiome(CHORUS_WILDS, VOID_GARDENS, 3.0);
        TheEndBiomes.addMidlandsBiome(PETRIFIED_ABYSS, PETRIFIED_ABYSS, 2.0);
        // Small islands get the sparse/barren variants.
        TheEndBiomes.addSmallIslandsBiome(SHATTERED_EXPANSE, 4.0);
        TheEndBiomes.addSmallIslandsBiome(ASTRAL_BARRENS, 3.0);
        // Barrens are the outer rim of a highlands biome.
        TheEndBiomes.addBarrensBiome(CHORUS_WILDS, ASTRAL_BARRENS, 3.0);
        TheEndBiomes.addBarrensBiome(PETRIFIED_ABYSS, SHATTERED_EXPANSE, 3.0);
        DragonBrain.LOGGER.debug("Registered {} End biomes with the biome source", BIOMES.size());
    }
}
